{
  "root_causes": [
    {
      "service": "ts-price-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-price-service' AND span_name IN ('SELECT ts.price_config','SELECT price_config') GROUP BY 1,2",
          "claim": "Price's SELECT price_config DB spans have p95 of 197s to 226s and p50 of 14s during the incident, with errors."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_pod_name AS pod, round(avg(value),2) avgv, round(max(value),2) maxv, count(*) n FROM abnormal_metrics_sum WHERE service_name='ts-price-service' AND metric IN ('db.client.connections.timeouts') GROUP BY 1,2,3",
          "claim": "ts-price-service DB connection pool shows timeouts (avg 3.5, max 5) in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(value),2) avgv, round(max(value),2) maxv, count(*) n FROM abnormal_metrics WHERE service_name='ts-price-service' AND metric IN ('db.client.connections.max','db.client.connections.usage','db.client.connections.idle.min') GROUP BY 1,2",
          "claim": "Price's DB connection pool is capped at 10 connections, with usage about 3 to 6 during the incident."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-price-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-basic-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Basic's client calls to price slow to p95 of about 14s to 37s with errors, while basic's calls inherit price's delay."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Travel's server span POST trips/left has p95 of 60s with errors, after basic's slow responses."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3",
          "claim": "Travel2 server and client spans show p95 of 20s to 56s with errors, following basic's degradation."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Preserve's server span POST preserve has p95 of about 49s during the incident, after basic's delays."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Route-plan server spans reach p95 of 60s to 84s with errors, reflecting slow calls to travel services."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Route-plan client spans to travel and travel2 reach p95 of about 58s, with errors."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Travel-plan server spans reach p95 of about 60s with errors, after route-plan's slow responses."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "UI dashboard client calls to travel-plan, travel and travel2 show p95 of 30s to 60s, with errors, when users are affected."
        }
      ]
    }
  ]
